/**
 * /components/TodoDemo.jsx
 * ---------------------------------------------------------------------------
 * Demo CRUD đơn giản trên state.todoList.
 */

import React, { useState } from 'react'
import { Card, Input, Button, List, Space, Tag, Empty, Popconfirm } from 'antd'
import { PlusOutlined, DeleteOutlined, CheckOutlined } from '@ant-design/icons'

import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'
import { useI18n } from '@/lang'
import { uuid } from '@/utils'

const TodoDemo = () => {
  const dispatch = useAppDispatch()
  const { t } = useI18n()
  const todoList = useAppSelector(getters.todoList)
  const todoCount = useAppSelector(getters.todoCount)
  const todoDoneCount = useAppSelector(getters.todoDoneCount)

  const [text, setText] = useState('')

  const addTodo = () => {
    const value = text.trim()
    if (!value) return
    dispatch(mutations.pushTodo({ id: uuid(), text: value, done: false }))
    setText('')
  }

  const toggleTodo = (id) => {
    const next = todoList.map((t) => (t.id === id ? { ...t, done: !t.done } : t))
    dispatch(mutations.setTodoList(next))
  }

  return (
    <Card
      title={t('Demo Todo (store/mutations.js)')}
      size="small"
      extra={
        <Space>
          <Tag color="blue">{t('Tổng: {{count}}', { count: todoCount })}</Tag>
          <Tag color="green">{t('Xong: {{count}}', { count: todoDoneCount })}</Tag>
        </Space>
      }
    >
      <Space.Compact className="todo-input-row">
        <Input
          placeholder={t('Nhập việc cần làm...')}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onPressEnter={addTodo}
        />
        <Button type="primary" icon={<PlusOutlined />} onClick={addTodo}>
          {t('Thêm')}
        </Button>
      </Space.Compact>

      {todoList.length === 0 ? (
        <Empty
          description={t('Chưa có dữ liệu')}
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        />
      ) : (
        <List
          size="small"
          bordered
          dataSource={todoList}
          renderItem={(item) => (
            <List.Item
              actions={[
                <Button
                  key="done"
                  type="text"
                  icon={<CheckOutlined />}
                  onClick={() => toggleTodo(item.id)}
                />,
                <Popconfirm
                  key="del"
                  title={t('Xoá việc này?')}
                  onConfirm={() => dispatch(mutations.removeTodo(item.id))}
                >
                  <Button type="text" danger icon={<DeleteOutlined />} />
                </Popconfirm>,
              ]}
            >
              <span className={item.done ? 'todo-text todo-text-done' : 'todo-text'}>
                {item.text}
              </span>
            </List.Item>
          )}
        />
      )}
    </Card>
  )
}

export default TodoDemo
