/**
 * /components/CounterDemo.jsx
 * ---------------------------------------------------------------------------
 * Demo đọc / ghi state qua Redux Toolkit (state.js + mutations.js + getters.js).
 */

import React from 'react'
import { Card, Button, Space, Typography, InputNumber, Tag } from 'antd'
import { PlusOutlined, MinusOutlined, ReloadOutlined } from '@ant-design/icons'

import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'
import { useI18n } from '@/lang'

const { Text } = Typography

const CounterDemo = () => {
  const dispatch = useAppDispatch()
  const { t } = useI18n()
  const counter = useAppSelector(getters.counter)

  return (
    <Card title={t('Demo Redux Toolkit (store/state.js)')} size="small">
      <Space direction="vertical" size="middle" className="full-width">
        <Space>
          <Text strong>{t('Giá trị hiện tại: {{value}}', { value: counter })}</Text>
          <Tag color="blue">getters.counter</Tag>
        </Space>

        <Space wrap>
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => dispatch(mutations.increase(1))}
          >
            {t('Tăng')}
          </Button>
          <Button
            icon={<MinusOutlined />}
            onClick={() => dispatch(mutations.decrease(1))}
          >
            {t('Giảm')}
          </Button>
          <InputNumber
            min={-9999}
            max={9999}
            value={counter}
            onChange={(v) => dispatch(mutations.setCounter(v ?? 0))}
          />
          <Button
            icon={<ReloadOutlined />}
            onClick={() => dispatch(mutations.setCounter(0))}
          >
            {t('Reset')}
          </Button>
        </Space>

        <Text type="secondary" className="text-xs">
          {t(
            'dispatch(mutations.increase(1)) — mutations được khai báo trong /store/mutations.js',
          )}
        </Text>
      </Space>
    </Card>
  )
}

export default CounterDemo
